def mean_squared_error(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate the mean squared error.
    Mean squared error is the average of the squares of the errors:
    MSE = average (x - x_mean) ** 2
    >>> mean_squared_error([1.0, 2.0, 3.0, 4.0])
    1.25
    """
    return sum((num - mean(numbers)) ** 2 for num in numbers) / len(numbers)


def mean_squared_log_error(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate the mean squared logarithmic error.
    Mean squared logarithmic error is a scale-invariant version of the mean squared error:
