def median(numbers: List[float]) -> float:
    """ For a given list of input numbers, return the median
    >>> median([1.0, 2.0, 3.0, 4.0])
    2.5
    """
    n = len(numbers)
    numbers.sort()
    if n == 0:
        return 0
    elif n % 2 == 0:
        return (numbers[n // 2 - 1] + numbers[n // 2]) / 2
    else:
        return numbers[n // 2]


