    if not numbers:
        return []
    else:
        return [numbers[0]] + insertion_sort(numbers[1:])


def list_sum(a: List[int], b: List[int]) -> List[int]:
    """ Given two lists 'a' and 'b' of numbers of the same length, compute the element-wise sum of them
    >>> list_sum([1, 2, 3], [3, 4, 5])
    [4, 6, 8]
    >>> list_sum([3, 2, 5], [5, 3, 1])
    [8, 5, 6]
    >>> list_sum([3, 2, 5], [-2, -4, -1])
    [1, -2, 4]
    >>> list_sum([3, 2, 5], [1, -4, -1])
    [4, -2, 4]
    >>> list_sum([3, 2, 5], [0, -4, -1])
    [3, -2, 4]
    """
    if not a:
        return []
    else:
        return [a[0] + b[0]] + list_sum(a[1:], b[1:])


def list_difference(a: List[int], b: List[int]) -> List[int]:
    """ Given two lists 'a' and 'b' of numbers of the same length, compute the element-wise difference of them
    >>> list_difference([1, 2, 3], [3, 4, 5])
    [-2, -2, -2]
    >>> list_difference([3, 2, 5], [5, 3, 1])
    [-2, -5, 4]
    >>> list_difference([3, 2, 5], [-2, -4, -1])
    [5, 6, 6]
    >>> list_difference([3, 2, 5], [1, -4, -1])
    [2, 6, 4]
    >>> list_difference([3, 2, 5], [0, -4, -1])
    [3, 6, 6]
    """
    if not a:
        return []
    else:
        return [a[0] - b[0]] + list_difference(a[1:], b[1:])


def list_product(a: List[int], b: List[int]) -> List[int]:
    """ Given two lists 'a' and 'b' of numbers of the same length, compute the element-wise product of them
    >>> list_product([1, 2, 3], [3, 4, 5])
    [3, 8, 15]
    >>> list_product([3, 2, 5], [5, 3, 1])
    [15, 6, 5]
    >>> list_product([3, 2, 5], [-2, -4, -1])
    [-6, -8, -5]
    >>> list_product([3, 2, 5], [1, -4, -1])
    [-3, -8, -5]
    >>> list_product([3, 2, 5], [0, -4, -1])
    [0, -8, -5]
    """
    if not a:
        return []
    else:
        return [a[0] * b[0]] + list_product(a[1:], b[1:])


