    """ Return a string containing space-delimited numbers starting from 0 upto n inclusive.
    >>> string_sequence_memoized(0)
    '0'
    >>> string_sequence_memoized(5)
    '0 1 2 3 4 5'
    """
    memo = {0: '0'}
    return string_sequence_memoized_helper(n, memo)

def string_sequence_memoized_helper(n: int, memo: Dict[int, str]) -> str:
    if n in memo:
        return memo[n]
    else:
        memo[n] = string_sequence_memoized_helper(n - 1, memo) + ' ' + str(n)
        return memo[n]

def string_sequence_memoized_with_cache(n: int) -> str:
    """ Return a string containing space-delimited numbers starting from 0 upto n inclusive.
    >>> string_sequence_memoized_with_cache(0)
    '0'
    >>> string_sequence_memoized_with_cache(5)
    '0 1 2 3 4 5'
    """
    @functools.lru_cache(maxsize=None)
    def memoized_helper(n: int) -> str:
        if n == 0:
            return '0'
        else:
            return memoized_helper(n - 1) + ' ' + str(n)
    return memoized_helper(n)

