def max_cmp(values: Iterable) -> int:
    """ Returns index of largest element in collection
    >>> max_cmp([5, 1, 8, 3, 2])
    2
    >>> max_cmp([])
    0
    """
    if len(values) == 0:
        return 0
    max_value = values[0]
    max_idx = 0
    for idx, value in enumerate(values):
        if value > max_value:
            max_value = value
            max_idx = idx
    return max_idx

def sum_dict(d: dict) -> dict:
    """ Convert dictionary of lists to dictionary of their sum
    >>> sum_dict({'foo': [1, 2], 'bar': [3, 4, 5]})
    {'foo': 3, 'bar': 12}
