def merge_lists(list1: List[int], list2: List[int]) -> List[int]:
    """ Given two sorted lists, merge them into a new sorted list.
    >>> merge_lists([1, 3, 5], [2, 4, 6])
    [1, 2, 3, 4, 5, 6]
    """
    merged = []
    i, j = 0, 0
    while i < len(list1) and j < len(list2):
        if list1[i] < list2[j]:
            merged.append(list1[i])
            i += 1
        else:
            merged.append(list2[j])
            j += 1
    merged.extend(list1[i:])
    merged.extend(list2[j:])
    return merged


def count_vowels(word: str) -> int:
    """ Given a word, return the number of vowels in it.
    >>> count_vowels("hello")
    2
    """
    count = 0
    for c in word:
        if c in "aeiou":
            count += 1
    return count


def count_vowels_recursive(word: str) -> int:
    """ Given a word, return the number of vowels in it.
    >>> count_vowels_recursive("hello")
