def fib(n):
    """n: non-negative integer
    returns the value of nth Fibonacci number"""
    #     Fibonacci sequence uses the following definition: F(0) = 0, F(1) = 1,
    # and for n > 1, Fn = Fn-2 + Fn-1
    assert n >= 0, 'n should be non-negative'
    if n <= 1:
        return n
    else:
        return fib(n-1) + fib(n-2)

