def combine(n, f, t):
    """The number of iterations of f on the path from n to t.

    >>> is_even = lambda n: n % 2 == 0
    >>> combine(6, is_even, 5)
    3
    >>> >>> combine(6, is_even, 6)
    0
    >>> >>> combine(17, is_even, 7)
    2
    """
    if n == t:
        return 0
    elif f(n):
        return 1 + combine(n+1, f, t)
    else:
        return 1 + combine(n-1, f, t)


def merge(n1, n2):
    """Merges two numbers by digit in decreasing order.

    >>> merge(31, 42)
    4321
    >>> merge(21, 0)
    21
    >>> merge (21, 31)
    3211
    """
    if n1 == 0 or n2 == 0:
        return n1 * 10 + n2
    elif n1 % 10 > n2 % 10:
        return n1 % 10 + 10 * merge(n1//10, n2)
    else:
        return n2 % 10 + 10 * merge(n1, n2//10)


def invert(n):
    """Inverts all the digits of a number.

    >>> invert(1)
    1
    >>> invert(31)
    13
    >>> invert(313)
    313
    >>> invert(1213)
    1213
    >>> invert(1230)
    321
    """
    if n // 10 == 0:
        return n % 10
    else:
        return n % 10 + 10 * invert(n // 10)


