def gcd(a: int, b: int):
    """Return greatest common divisor of a and b.
    >>> gcd(5, 10)
    5
    >>> gcd(10, 5)
    5
    >>> gcd(5, 5)
    5
    >>> gcd(100, 99)
    1
    """
    if a < 0 or b < 0:
        return None
    if a == 0:
        return b
    if b == 0:
        return a
    if a == b:
        return a
    if a > b:
        return gcd(a - b, b)
    return gcd(a, b - a)

