def count_reciprocal_prime_digits(n):
    """Return the number of digits in n that are the unique prime factors of n.

    >>> count_reciprocal_prime_digits(15)
    0
    >>> count_reciprocal_prime_digits(56)
    1
    >>> count_reciprocal_prime_digits(627)
    3
    """
    def split(i):
        return 10**(len(str(i))-1), i - 10**(len(str(i))-1)

    def is_prime(x):
        return x>1 and all(x%i for i in range(2, int(sqrt(x))+1))

    def split_prime(x):
        if is_prime(x): return [x]
        elif is_prime(x//10): return [x//10]
        elif is_prime(x%10): return [x%10]
        else: return split_prime(x//10) + split_prime(x%10)

    return sum([x in [x for x in split_prime(n)] for x in str(n)])

