def count(K):
    """Returns a dictionary with keys the positive integers less than
    or equal to K and values the number of possible lists consisting of
    only those elements that are keys and are either greater than or
    equal to 1, or their additive inverses.

    >>> count(5)
    {1: 2, 2: 4, 3: 8, 4: 16, 5: 32}
    """
    def iter_count(i, D):
        if i == K + 1:
            return D
        else:
            ans = {}
            for x in D:
                ans[x] = D[x]
                ans[-x] = D[x]
            return iter_count(i + 1, ans)

    return iter_count(1, {1:1})

