def countDigits(limit: int):
    if limit <= 10:
        return countDigits.__dict__['cache'][limit]
    cache = dict(countDigits.__dict__.get('cache', {}), **{i : 0 for i in range(2, limit + 1)})
    for i in range(2, limit + 1):
        j = i
        while j % 2 == 0:
            j //= 2
        while j % 5 == 0:
            j //= 5
        countDigits.__dict__['cache'][i] = countDigits.__dict__['cache'][j] + 1
    return sum(cache.values())

