def manhattan_distance(a: Point, b: Point):
    return abs(a.x - b.x) + abs(a.y - b.y)


def closest_intersection(a: Point, b: Point, distance: int):
    if manhattan_distance(a, b) > distance:
        return manhattan_distance(a, b)
