        return float("inf")


class Point:
    """
    A simple point class.
    """

    def __init__(self, x, y, x_steps=0, y_steps=0):
        self.x = x
        self.y = y
        self.x_steps = x_steps
        self.y_steps = y_steps

    def __str__(self):
        return f"({self.x}, {self.y}, {self.x_steps}, {self.y_steps})"

    def __repr__(self):
        return self.__str__()

    def move(self, direction, move, number_of_steps):
        """
        Update position of the point by given direction and moves.
        """
        if direction == UP:
            self.y_steps = number_of_steps
            self.y = self.y + number_of_steps * move
        elif direction == DOWN:
            self.y_steps = number_of_steps
            self.y = self.y - number_of_steps * move
        elif direction == LEFT:
            self.x_steps = number_of_steps
            self.x = self.x - number_of_steps * move
        elif direction == RIGHT:
            self.x_steps = number_of_steps
            self.x = self.x + number_of_steps * move
        else:
            raise NotImplementedError

    def distance(self, other):
        """
        Computes Manhattan distance between this point and given other point.
        """
        return abs(self.x - other.x) + abs(self.y - other.y)


