from collections import defaultdict
from itertools import permutations


def popular(items: list, sort: bool = True):
    """Given list of items (repeated as many times as necessary),
    return list of (items, count).
    >>> popular(['a', 'a', 'b'], sort=True)
    [('a', 2), ('b', 1)]
    >>> popular(['a', 'a', 'b'], sort=False)
    [('b', 1), ('a', 2)]
    """
    m = defaultdict(int)
    for item in items:
        m[item] += 1
    if sort:
        m = sorted(m.items(), key=lambda x: x[1], reverse=True)
        return [i for i, j in m]
    else:
        return [i for i, j in m]

