    """ s is a string of digit only.
    return the digit obtained by evaluating the arithmetic expression
    represented by s.
    """
    stack = []
    for c in s:
        if c.isdigit():
            stack.append(int(c))
        else:
            b = stack.pop()
            a = stack.pop()
            if c == '+':
                stack.append(a + b)
            elif c == '-':
                stack.append(a - b)
            elif c == '*':
                stack.append(a * b)
            elif c == '/':
                stack.append(a // b)
    return stack.pop()

