# 24. Write a function that takes a string as an input and returns a list of all the
# permutations of that string.
# permutation('abc') => ['abc', 'acb', 'bac', 'bca', 'cab', 'cba']

def permutation(word):
    if len(word) == 1:
        return [word]
    else:
        result = []
        for i, letter in enumerate(word):
            remaining_chars = word[:i] + word[i+1:]
            for permutation in permutation(remaining_chars):
                result.append(letter + permutation)
        return result


