def adjacent_product(nums):
    """Given a list of integers, find the pair of adjacent elements that has the largest product and return that product.

    adjacent_product([3, 6, -2, -5, 7, 3]) => 21
    """
    product = 0
    for i in range(len(nums)-1):
        if product < nums[i] * nums[i+1]:
            product = nums[i] * nums[i+1]
    return product

