def binary_conversion(n):
    """The function will convert a given decimal number (n) into its corresponding
    binary representation as an integer

    For example:
    >>> binary_conversion(65)
    1000001

    """
    if n < 0:
        raise ValueError("You must provide a non-negative integer")
    if n == 0:
        return 0
    binary_string = ""
    while n > 0:
        binary_string = str(n % 2) + binary_string
        n //= 2
    return int(binary_string)

