    convert_base("1001", 5, 5) ==> "1001"
    '''
    decimal_number = 0
    for i, digit in enumerate(num_as_string[::-1]):
        decimal_number += int(digit) * b1 ** i
    result = []
    while decimal_number:
        result.append(str(decimal_number % b2))
        decimal_number //= b2
    return ''.join(result[::-1])

